        static Field opt(String name, Type type) { return new Field(name, type, false); }
    }

    /** A RESPONSE contract changes from before to after. What breaks a client that was built against before? */
    static List<String> breaksOldReaders(List<Field> before, List<Field> after, boolean readerFailsOnUnknown) {
