    }

    /** A REQUEST contract changes from before to after. What breaks a client that still sends before-shaped bodies? */
    static List<String> breaksOldWriters(List<Field> before, List<Field> after, boolean serverFailsOnUnknown) {
        throw new UnsupportedOperationException("TODO: new required fields, fields that became required, type changes, dropped fields for a strict server");
    }

