    public static void main(String[] args) {
        var orderV1 = List.of(Field.req("id", Type.STRING), Field.req("total", Type.NUMBER), Field.opt("note", Type.STRING));
        test("adding an optional response field breaks only readers that fail on unknown properties", () -> {
            var v2 = List.of(Field.req("id", Type.STRING), Field.req("total", Type.NUMBER), Field.opt("note", Type.STRING), Field.opt("discount", Type.NUMBER));
            eq(List.of(breaksOldReaders(orderV1, v2, false), breaksOldReaders(orderV1, v2, true)), List.of(List.of(), List.of("unknown: discount")));
