// ─────────────────────────────────────────────────────────────────────────
//  01 · contract changes★★☆
//  concepts: tolerant reader · required versus optional · a rename is remove + add · two directions
// ─────────────────────────────────────────────────────────────────────────

import static bootcamp.Check.*;

import java.util.*;

class Exercise {

    enum Type { STRING, NUMBER, BOOLEAN, OBJECT, ARRAY }

    /** One property of a JSON contract: its name, its JSON type, and whether it is always present. */
    record Field(String name, Type type, boolean required) {
        static Field req(String name, Type type) { return new Field(name, type, true); }
        static Field opt(String name, Type type) { return new Field(name, type, false); }
    }

    static Map<String, Field> byName(List<Field> fields) {
        var out = new LinkedHashMap<String, Field>();
        for (var f : fields) out.put(f.name(), f);
        return out;
    }

    /** A RESPONSE contract changes from before to after. What breaks a client that was built against before? */
    static List<String> breaksOldReaders(List<Field> before, List<Field> after, boolean readerFailsOnUnknown) {
        var was = byName(before);
        var now = byName(after);
        var out = new TreeSet<String>();
        for (var old : was.values()) {
            var f = now.get(old.name());
            if (f == null) {
                if (old.required()) out.add("removed: " + old.name());
            } else if (f.type() != old.type()) {
                out.add("type changed: " + old.name());
            } else if (old.required() && !f.required()) {
                out.add("may be missing: " + old.name());
            }
        }
        if (readerFailsOnUnknown) {
            for (var f : now.values()) if (!was.containsKey(f.name())) out.add("unknown: " + f.name());
        }
        return List.copyOf(out);
    }

    /** A REQUEST contract changes from before to after. What breaks a client that still sends before-shaped bodies? */
    static List<String> breaksOldWriters(List<Field> before, List<Field> after, boolean serverFailsOnUnknown) {
        var was = byName(before);
        var now = byName(after);
        var out = new TreeSet<String>();
        for (var f : now.values()) {
            var old = was.get(f.name());
            if (old == null) {
                if (f.required()) out.add("new required: " + f.name());
            } else if (f.type() != old.type()) {
                out.add("type changed: " + f.name());
            } else if (f.required() && !old.required()) {
                out.add("now required: " + f.name());
            }
        }
        if (serverFailsOnUnknown) {
            for (var old : was.values()) if (!now.containsKey(old.name())) out.add("no longer accepted: " + old.name());
        }
        return List.copyOf(out);
    }

    // ─── tests ───────────────────────────────────────────────────────────
    public static void main(String[] args) {
        var orderV1 = List.of(Field.req("id", Type.STRING), Field.req("total", Type.NUMBER), Field.opt("note", Type.STRING));
        test("adding an optional response field breaks only readers that fail on unknown properties", () -> {
            var v2 = List.of(Field.req("id", Type.STRING), Field.req("total", Type.NUMBER), Field.opt("note", Type.STRING), Field.opt("discount", Type.NUMBER));
            eq(List.of(breaksOldReaders(orderV1, v2, false), breaksOldReaders(orderV1, v2, true)), List.of(List.of(), List.of("unknown: discount")));
        });
        test("removing a response field: a required one breaks readers, an optional one does not", () -> {
            var noNote = List.of(Field.req("id", Type.STRING), Field.req("total", Type.NUMBER));
            var noTotal = List.of(Field.req("id", Type.STRING), Field.opt("note", Type.STRING));
            eq(List.of(breaksOldReaders(orderV1, noNote, false), breaksOldReaders(orderV1, noTotal, false)), List.of(List.of(), List.of("removed: total")));
        });
        test("a renamed field is a removal plus an addition", () -> {
            var renamed = List.of(Field.req("id", Type.STRING), Field.req("amount", Type.NUMBER), Field.opt("note", Type.STRING));
            eq(List.of(breaksOldReaders(orderV1, renamed, false), breaksOldReaders(orderV1, renamed, true)),
               List.of(List.of("removed: total"), List.of("removed: total", "unknown: amount")));
        });
        test("a required response field that becomes optional breaks readers; the reverse does not", () -> {
            var loose = List.of(Field.req("id", Type.STRING), Field.opt("total", Type.NUMBER), Field.opt("note", Type.STRING));
            var strict = List.of(Field.req("id", Type.STRING), Field.req("total", Type.NUMBER), Field.req("note", Type.STRING));
            eq(List.of(breaksOldReaders(orderV1, loose, false), breaksOldReaders(orderV1, strict, false)), List.of(List.of("may be missing: total"), List.of()));
