        test("a type change breaks readers and writers, reported once per field", () -> {
            var asText = List.of(Field.req("id", Type.STRING), Field.req("total", Type.STRING), Field.opt("note", Type.STRING));
            eq(List.of(breaksOldReaders(orderV1, asText, true), breaksOldWriters(orderV1, asText, true)), List.of(List.of("type changed: total"), List.of("type changed: total")));
        });
        test("requests: a new required field or a field made required breaks old writers, a new optional one does not", () -> {
            var v2 = List.of(Field.req("id", Type.STRING), Field.req("total", Type.NUMBER), Field.req("note", Type.STRING),
