    /** Absent keeps the current value; present (even null) replaces it. */
    static String text(Map<String, Object> patch, String key, String current) {
        return patch.containsKey(key) ? (String) patch.get(key) : current;
    }

    // Given: test helpers. A parsed JSON body is a map, and it may hold explicit nulls.
    static Map<String, Object> body(Object... keysAndValues) {
        var m = new LinkedHashMap<String, Object>();
        for (int i = 0; i < keysAndValues.length; i += 2) m.put((String) keysAndValues[i], keysAndValues[i + 1]);
        return m;
    }
    static Object outcome(Customer current, Map<String, Object> patch) {
        try { return applyPatch(current, patch); } catch (PatchRejected rejected) { return rejected.errors(); }
    }
    static final Customer ANA = new Customer("Ana", "ana@x.io", "+351 900", 120);

    // ─── tests ───────────────────────────────────────────────────────────
    public static void main(String[] args) {
        test("an absent key keeps the current value", () -> {
            eq(outcome(ANA, body("email", "ana@new.io")), new Customer("Ana", "ana@new.io", "+351 900", 120));
        });
        test("an explicit null clears a nullable field", () -> {
            eq(outcome(ANA, body("phone", null)), new Customer("Ana", "ana@x.io", null, 120));
        });
        test("null for a field that cannot be empty is refused", () -> {
            eq(outcome(ANA, body("name", null)), List.of("name: cannot be null"));
        });
        test("an unknown key is refused, not silently ignored", () -> {
            eq(outcome(ANA, body("emial", "ana@new.io")), List.of("emial: unknown field"));
        });
        test("a value of the wrong JSON type is refused", () -> {
            eq(outcome(ANA, body("loyaltyPoints", "150")), List.of("loyaltyPoints: wrong type"));
        });
        test("every problem is reported, sorted, and nothing is applied", () -> {
            eq(outcome(ANA, body("phone", "+351 911", "zip", "1000", "name", null, "loyaltyPoints", 1.5)),
               List.of("loyaltyPoints: wrong type", "name: cannot be null", "zip: unknown field"));
        });
        test("an empty patch changes nothing (boundary)", () -> {
            eq(outcome(ANA, body()), ANA);
        });
        System.exit(report());
    }
    // ─── end tests ───────────────────────────────────────────────────────
}
